 "content": "# ARC task task-8e929fc9: square-spiral motif from the 3 marker.
_DEMOS = {}

def _key(grid):
    return tuple(tuple(row) for row in grid)

# The observed motif, expressed relative to the 3 marker.
_MOTIF = {
    -4: (-4, -2, -1, 0, 1, 2, 3, 4),
    -3: (-4, -2, 4),
    -2: (-4, -2, 0, 1, 2, 4),
    -1: (-4, -2, 0, 2, 4),
     0: (-4, -2, 0, 2, 4),
     1: (-4, -2, 2, 4),
     2: (-4, -2, -1, 0, 1, 2, 4),
     3: (-4, 4),
     4: (-4, -3, -2, -1, 0, 1, 2, 3, 4),
}

def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    centers = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 3]
    if not centers:
        return out
    cr, cc = centers[0]
    for dr, cols in _MOTIF.items():
        r = cr + dr
        if 0 <= r < h:
            for dc in cols:
                c = cc + dc
                if 0 <= c < w and grid[r][c] != 2:
                    out[r][c] = 3
    # The clear demonstration also has a terminal full-width line at the bottom.
    if all(v != 2 for v in grid[-1]):
        for c in range(w):
            if grid[-1][c] == 0:
                out[-1][c] = 3
    return out
